static const jas_opt_t *jas_optlookup(const jas_opt_t *opts, const char *name) /* <=== jas_optlookup */ 
{
	const jas_opt_t *opt;

	for (opt = opts; opt->id >= 0 && opt->name; ++opt) {
		if (!strcmp(opt->name, name)) {
			return opt;
		}
	}
	return 0;
}

